var out = [];
if (gs.getCurrentScopeName() !== 'rhino.global') {
  gs.info('BCFA_DEPLOY8 ABORTED: run in scope "global", current scope is ' + gs.getCurrentScopeName());
} else {
  var gum = new GlideUpdateManager2();
  var ok = 0, failed = 0;
  files.forEach(function(f) {
    try { gum.loadXML(f.xml); ok++; }
    catch (e) { failed++; out.push('FAILED ' + f.name + ': ' + e); }
  });
  var agent = new GlideRecord('sn_aia_agent');
  agent.addEncodedQuery('nameSTARTSWITHBCFA AP');
  agent.query();
  var agents = [];
  while (agent.next()) agents.push(agent.getValue('name') + ' scope=' + agent.getValue('sys_scope'));
  out.unshift('loaded=' + ok + ' failed=' + failed + ' of ' + files.length + ' | agents: ' + agents.join('; '));
}
gs.info('BCFA_DEPLOY8 ' + out.join(' | '));
